import{agent,methods,ndJsonStream}from"#compiled/@agentclientprotocol/sdk/index.js";import{Readable,Writable}from"node:stream";import{EveAcpAdapter}from"#acp/adapter.js";import{limitAcpLineBytes}from"#acp/line-limit.js";async function runAcpServer(e){await runAcpServerOnStreams(e,{input:process.stdin,output:process.stdout})}async function runAcpServerOnStreams(r,i){let a=new EveAcpAdapter(r),o=agent({name:`eve`}).onRequest(methods.agent.initialize,({params:e})=>a.initialize(e)).onRequest(methods.agent.session.new,({params:e})=>a.newSession(e)).onRequest(methods.agent.session.prompt,({params:e,client:t,signal:n})=>a.prompt(e,t,n)).onRequest(methods.agent.session.close,({params:e})=>a.closeSession(e.sessionId)).onNotification(methods.agent.session.cancel,({params:e})=>a.cancel(e.sessionId)),s=Writable.toWeb(i.output),c=Readable.toWeb(i.input).pipeThrough(limitAcpLineBytes()),l=o.connect(ndJsonStream(s,c)),close=()=>l.close();r.signal?.aborted?close():r.signal?.addEventListener(`abort`,close,{once:!0});try{await l.closed}finally{r.signal?.removeEventListener(`abort`,close),await a.close()}}export{runAcpServer,runAcpServerOnStreams};